// src/utils/gapgptProvider.ts
var GAPGPT_BASE_URL = (process.env.GAPGPT_BASE_URL || "https://api.gapgpt.app/v1").replace(/\/$/, "");
var GAPGPT_TTS_URL = process.env.GAPGPT_TTS_URL || "https://gapgpt.app/api/v1/tts";
var GAPGPT_CHAT_MODELS = [
  process.env.GAPGPT_CHAT_MODEL || "gpt-4o",
  "gemini-2.0-flash",
  "gemini",
  "gpt-4o-mini",
  "gpt-5.6-luna"
];
function getGapgptApiKey() {
  return (process.env.GAPGPT_API_KEY || "").trim();
}
function isGapgptConfigured() {
  return Boolean(getGapgptApiKey());
}
async function gapgptSynthesizeSpeech(text, voice = "en-male-1") {
  const key = getGapgptApiKey();
  if (!key) return null;
  const clean = String(text || "").trim().slice(0, 4e3);
  if (!clean) return null;
  try {
    const res = await fetch(GAPGPT_TTS_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ text: clean, voice })
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => "");
      console.warn("GapGPT TTS failed:", res.status, errText.slice(0, 180));
      return null;
    }
    const contentType = res.headers.get("content-type") || "audio/mpeg";
    if (contentType.includes("application/json")) {
      const data = await res.json();
      if (data?.audioBase64) {
        return {
          buffer: Buffer.from(data.audioBase64, "base64"),
          mimeType: data.mimeType || "audio/mpeg",
          engine: "gapgpt-tts"
        };
      }
      if (data?.url) {
        const audioRes = await fetch(data.url);
        if (audioRes.ok) {
          return {
            buffer: Buffer.from(await audioRes.arrayBuffer()),
            mimeType: audioRes.headers.get("content-type") || "audio/mpeg",
            engine: "gapgpt-tts-url"
          };
        }
      }
      return null;
    }
    return {
      buffer: Buffer.from(await res.arrayBuffer()),
      mimeType: contentType.split(";")[0] || "audio/mpeg",
      engine: "gapgpt-tts"
    };
  } catch (e) {
    console.warn("GapGPT TTS exception:", e);
    return null;
  }
}

